async def act(page):
    """
    From the current page state: dismiss the visible test popup if present, scroll to the bottom
    to reveal pagination controls, then navigate to page 2 of the blog feed. The navigation-causing
    click is performed as the final awaited action.
    """

    # Attempt to close any blocking popup that contains the known text
    closed = await page.evaluate('''() => {
        try {
            const matches = Array.from(document.querySelectorAll('*')).filter(n => (n.textContent || '').includes('This is a test popup!'));
            if (matches.length === 0) return false;
            const node = matches[0];
            const container = node.closest('dialog, section, form, div') || node.parentElement;
            if (!container) return false;

            const closeSelectors = [
                'button[aria-label*="close" i]',
                '[role="button"][aria-label*="close" i]',
                'button[title*="close" i]',
                '.popup-close',
                '.pp-close',
                '.mfp-close',
                '.modal-close',
                '.fancybox-close',
                '.ui-dialog-titlebar-close',
                '.close',
                'button.close',
                'a.close'
            ];

            for (const sel of closeSelectors) {
                const btn = container.querySelector(sel);
                if (btn) { btn.click(); return true; }
            }

            // Try any button/link inside the container whose text looks like an X or whose aria-label mentions close
            const candidates = Array.from(container.querySelectorAll('button, a, span, i'));
            for (const el of candidates) {
                const t = (el.textContent || '').trim();
                if (t === '×' || t === 'x' || t === 'X' || t === '✖' || t === '✕') { el.click(); return true; }
                const aria = (el.getAttribute && (el.getAttribute('aria-label') || '')).toLowerCase();
                if (aria.includes('close')) { el.click(); return true; }
            }

            // Final fallback: attempt to click a point near the top-right of the container
            const rect = container.getBoundingClientRect();
            if (rect.width > 0 && rect.height > 0) {
                const clickX = Math.min(window.innerWidth - 1, Math.floor(rect.right) - 6);
                const clickY = Math.max(1, Math.floor(rect.top) + 6);
                const el = document.elementFromPoint(clickX, clickY);
                if (el) { el.click(); return true; }
            }
            return false;
        } catch (e) {
            return false;
        }
    }''')

    if closed:
        await page.wait_for_timeout(400)

    # Scroll to the bottom to reveal any lazy-loaded pagination
    await page.evaluate("() => { window.scrollTo(0, document.body.scrollHeight); }")
    await page.wait_for_timeout(700)

    # Final click: find and click a pagination link for page 2 using DOM heuristics (do this as the last awaited action)
    # We avoid Playwright role locators here because a previous run resolved an ambiguous locator to a post link and timed out.
    clicked = await page.evaluate('''() => {
        try {
            const anchors = Array.from(document.querySelectorAll('a'));
            // Helper to determine if element is likely visible/clickable
            function isVisible(el) {
                const style = window.getComputedStyle(el);
                if (style && (style.display === 'none' || style.visibility === 'hidden' || parseFloat(style.opacity || '1') === 0)) return false;
                const rect = el.getBoundingClientRect();
                return rect.width > 0 && rect.height > 0;
            }

            // First preference: an anchor whose visible text is exactly '2'
            for (const a of anchors) {
                if (!isVisible(a)) continue;
                const text = (a.textContent || '').trim();
                if (text === '2') { a.click(); return true; }
            }

            // Next: anchors whose aria-label or title mentions "page 2" or whose visible text contains 'Page 2'
            for (const a of anchors) {
                if (!isVisible(a)) continue;
                const aria = (a.getAttribute('aria-label') || '').toLowerCase();
                const title = (a.getAttribute('title') || '').toLowerCase();
                const text = (a.textContent || '').trim().toLowerCase();
                if (aria.includes('page 2') || title.includes('page 2') || text === 'page 2') { a.click(); return true; }
            }

            // Finally: anchors whose href looks like a page-2 URL (common patterns)
            for (const a of anchors) {
                if (!isVisible(a)) continue;
                const href = (a.getAttribute('href') || '').trim();
                if (!href) continue;
                try {
                    const u = new URL(href, location.href);
                    if (u.pathname.includes('/page/2') || u.searchParams.get('paged') === '2' || u.searchParams.get('page') === '2' || u.searchParams.get('p') === '2') {
                        a.click(); return true;
                    }
                } catch (err) {
                    // ignore malformed URLs
                    if (href.includes('page/2') || href.includes('paged=2') || href.includes('page=2') || /[?&]p=2(\b|$)/.test(href)) {
                        a.click(); return true;
                    }
                }
            }

            // As an additional fallback, try to click a link whose visible text includes 'Older' (common WP pagination label)
            for (const a of anchors) {
                if (!isVisible(a)) continue;
                const text = (a.textContent || '').trim().toLowerCase();
                if (text.includes('older') || text.includes('older posts') || text.includes('older entries') || text.includes('next')) { a.click(); return true; }
            }

            return false;
        } catch (e) {
            return false;
        }
    }''')

    # If clicked is True, we navigated away; end the function. Otherwise nothing more to do.
    if clicked:
        return

    return

